# ---------------------------------------------------------------------------
# Exact planner and certificate auditor (MODEL.md, CERTIFICATES.md).
# ---------------------------------------------------------------------------

import heapq
import para
import topo


def envelope(fab, guard):
    """Minimal error allowance / elapsed age for every phase-device.

    The search runs over the phase-device graph whose edges are the local
    waiting intervals and the eligible direct message transfers.  Labels are
    compared lexicographically on (bound, age) so the tie break requested by
    MODEL.md ("among equal minima find the minimum elapsed age") is honoured.
    """
    P, N = fab.P, fab.N
    V = P * N
    bnd = [None] * V
    age = [0] * V
    pvid = [None] * V
    pkind = [None] * V
    heap = []
    for p in range(P):
        base = p * N
        for i in fab.anchor_nodes[p]:
            v = base + i
            if bnd[v] is None:
                bnd[v] = 0
                age[v] = 0
                heap.append((0, 0, v))
    heapq.heapify(heap)
    push = heapq.heappush
    pop = heapq.heappop
    edges = fab.edges
    drift_allow = fab.drift_allow
    S = fab.S
    while heap:
        b, a, v = pop(heap)
        if bnd[v] != b or age[v] != a:
            continue
        p, i = divmod(v, N)
        # local waiting interval
        nb = b + drift_allow[p][i]
        na = a + 1
        u = ((p + 1) % P) * N + i
        ob = bnd[u]
        if ob is None or nb < ob or (nb == ob and na < age[u]):
            bnd[u] = nb
            age[u] = na
            pvid[u] = v
            pkind[u] = -1
            push(heap, (nb, na, u))
        # eligible direct message transfers
        rho_p = fab.rho[p]
        if rho_p < guard:
            continue
        lst = edges[p].get(i)
        if not lst:
            continue
        limit = S - rho_p - guard
        for (dst, delta, cost, code, delay) in lst:
            if delay > limit:
                continue
            nb = b + cost
            na = a + delta
            u = ((p + delta) % P) * N + dst
            ob = bnd[u]
            if ob is None or nb < ob or (nb == ob and na < age[u]):
                bnd[u] = nb
                age[u] = na
                pvid[u] = v
                pkind[u] = code
                push(heap, (nb, na, u))
    return bnd, age, pvid, pkind


def peak_of(fab, bnd):
    """All time error peak of one guard setting (None when unknown)."""
    P, N = fab.P, fab.N
    peak = 0
    for p in range(P):
        base = p * N
        allow = fab.drift_allow[p]
        for i in range(N):
            b = bnd[base + i]
            if b is None:
                return None
            v = b + allow[i]
            if v > peak:
                peak = v
    return peak


def warmup_of(fab, age):
    """Smallest cycle in which every phase-device attains its minimal bound."""
    P, N = fab.P, fab.N
    warm = 0
    for p in range(P):
        base = p * N
        for i in range(N):
            m = (age[base + i] - p + P - 1) // P
            if m > warm:
                warm = m
    return warm


def _safe(peak, guard, reconfig_ns):
    if peak is None:
        return False
    return guard * 1000 >= peak + reconfig_ns * 1000


def compile_plan(profile, fabric):
    """Exact periodic plan for one fabric."""
    cal = para.Calibration(profile)
    if not cal.feasible:
        return {"status": "inconsistent", "cycle": cal.cycle}
    fab = topo.Fabric(fabric, cal)
    peaks = []
    chosen = None
    chosen_data = None
    for g in fab.guards:
        bnd, age, pvid, pkind = envelope(fab, g)
        peak = peak_of(fab, bnd)
        peaks.append(peak)
        if chosen is None and _safe(peak, g, fab.reconfig_ns):
            chosen = g
            chosen_data = (bnd, age, pvid, pkind)
    out = {"status": "ok", "profile": cal.artifact(), "period_rounds": fab.P,
           "peaks_as": peaks, "guard_ns": chosen}
    if chosen is None:
        out["bounds_as"] = None
        out["age_rounds"] = None
        out["pred"] = None
        out["warmup_cycle"] = None
        return out
    bnd, age, pvid, pkind = chosen_data
    P, N = fab.P, fab.N
    bounds = []
    ages = []
    preds = []
    for p in range(P):
        base = p * N
        bounds.append(bnd[base:base + N])
        ages.append(age[base:base + N])
        row = []
        for i in range(N):
            v = base + i
            pv = pvid[v]
            row.append(None if pv is None else [pv, pkind[v]])
        preds.append(row)
    out["bounds_as"] = bounds
    out["age_rounds"] = ages
    out["pred"] = preds
    out["warmup_cycle"] = warmup_of(fab, age)
    return out


# ---------------------------------------------------------------------------
# Auditor
# ---------------------------------------------------------------------------

def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


def _valid_cycle(cal, cyc):
    """Check a claimed inconsistency proof.

    The published numbering is one based; the zero based variant is accepted
    as well so that either convention proves the same negative cycle.
    """
    if not isinstance(cyc, list) or not cyc:
        return False
    nedges = len(cal.edges)
    for base in (1, 0):
        ids = []
        ok = True
        for c in cyc:
            if not _is_int(c):
                ok = False
                break
            idx = c - base
            if idx < 0 or idx >= nedges:
                ok = False
                break
            ids.append(idx)
        if not ok or not ids:
            continue
        weight = 0
        good = True
        for k in range(len(ids)):
            e = cal.edges[ids[k]]
            nxt = cal.edges[ids[(k + 1) % len(ids)]]
            if e[1] != nxt[0]:
                good = False
                break
            weight += e[2]
        if good and weight < 0:
            return True
    return False


def _check_calibration_certificate(cal, cert):
    """Feasibility, tightness and witness validity of a calibration artifact."""
    if not isinstance(cert, dict) or cert.get('status') != 'ok':
        return False
    up = cert.get('upper_ps')
    pr = cert.get('pred')
    K = cal.K
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    for a in range(K):
        row = up[a]
        if not isinstance(row, list) or len(row) != K:
            return False
        for value in row:
            if not _is_int(value):
                return False
        prow = pr[a]
        if not isinstance(prow, list) or len(prow) != K:
            return False
        if prow[a] is not None:
            return False
        # every row is itself a feasible bias vector
        for (b0, b1, L, U) in cal.measurements:
            d = row[b1] - row[b0]
            if d < L or d > U:
                return False
        # witnesses: follow the predecessors back to the source
        for b in range(K):
            if b == a:
                continue
            cid = prow[b]
            if not _is_int(cid) or cid < 0 or cid >= len(cal.edges):
                return False
            total = 0
            cur = b
            steps = 0
            while True:
                edge = cal.edges[cid]
                if edge[1] != cur:
                    return False
                total += edge[2]
                nxt = edge[0]
                if nxt == a:
                    break
                if nxt == cur:
                    return False
                cid2 = prow[nxt]
                if not _is_int(cid2) or cid2 < 0 or cid2 >= len(cal.edges):
                    return False
                cid = cid2
                cur = nxt
                steps += 1
                if steps > K:
                    return False
            if total != row[b]:
                return False
    return True


def _step_of(fab, guard, src_phase, code):
    """Description of a directed transfer that starts at ``src_phase``."""
    if not _is_int(code) or code < 0 or code >= 2 * fab.nlinks:
        return None
    lid = code // 2
    direction = code % 2
    link = fab.links[lid]
    e0 = link['ends'][0]
    e1 = link['ends'][1]
    if direction == 0:
        src = int(e0[0]); dst = int(e1[0]); delay = int(link['delay_ns'][0]); defer = int(link['defer_rounds'][0])
    else:
        src = int(e1[0]); dst = int(e0[0]); delay = int(link['delay_ns'][1]); defer = int(link['defer_rounds'][1])
    if lid not in fab.slice_set[fab.slice_of[src_phase]]:
        return None
    rho_p = fab.rho[src_phase]
    if rho_p < guard or rho_p + delay + guard > fab.S:
        return None
    if fab.blocked(lid, src_phase, delay):
        return None
    x1 = rho_p + delay
    delta = (x1 + fab.T - 1) // fab.T + defer
    cost = fab.allow_by_code[code] + fab.ageing(src_phase, dst, x1, delta)
    return (src, dst, delta, cost, (src_phase + delta) % fab.P)


def _check_plan_witnesses(fab, guard, bounds, ages, preds, our_bounds, our_ages):
    """Validate the attaining paths and the certificate inequalities."""
    P, N = fab.P, fab.N
    V = P * N
    # shape and cell types
    for name, mat in (('bounds_as', bounds), ('age_rounds', ages), ('pred', preds)):
        if not isinstance(mat, list) or len(mat) != P:
            return False
        for row in mat:
            if not isinstance(row, list) or len(row) != N:
                return False
    for p in range(P):
        base = p * N
        for i in range(N):
            v = base + i
            b = bounds[p][i]
            a = ages[p][i]
            if b is None or a is None:
                if not (b is None and a is None and preds[p][i] is None):
                    return False
                if our_bounds[v] is not None:
                    return False
                continue
            if not _is_int(b) or not _is_int(a) or b < 0 or a < 0:
                return False
            cell = preds[p][i]
            if cell is None:
                # only anchors may stand alone
                if b != 0 or a != 0:
                    return False
                if i not in fab.anchor_nodes[p]:
                    return False
                continue
            if not isinstance(cell, list) or len(cell) != 2:
                return False
            prev = cell[0]
            kind = cell[1]
            if not _is_int(prev) or not _is_int(kind):
                return False
            if prev < 0 or prev >= V:
                return False
            pp, pi = divmod(prev, N)
            if kind == -1:
                if pi != i or pp != (p - 1) % P:
                    return False
                step_b = fab.drift_allow[pp][i]
                step_a = 1
            else:
                info = _step_of(fab, guard, pp, kind)
                if info is None:
                    return False
                src, dst, delta, cost, dst_phase = info
                if pi != src or dst != i or dst_phase != p:
                    return False
                step_b = cost
                step_a = delta
            if bounds[pp][pi] is None or ages[pp][pi] is None:
                return False
            if b != bounds[pp][pi] + step_b:
                return False
            if a != ages[pp][pi] + step_a:
                return False
    # every witness chain terminates at an anchor (ages strictly decrease)
    for p in range(P):
        base = p * N
        for i in range(N):
            if bounds[p][i] is None:
                continue
            v = base + i
            seen = 0
            cur = v
            while True:
                cell = preds[cur // N][cur % N]
                if cell is None:
                    if bounds[cur // N][cur % N] != 0 or ages[cur // N][cur % N] != 0:
                        return False
                    if cur % N not in fab.anchor_nodes[cur // N]:
                        return False
                    break
                cur = cell[0]
                seen += 1
                if seen > V:
                    return False
    # certificate inequalities: every allowed step out of a finite cell
    for p in range(P):
        base = p * N
        rho_p = fab.rho[p]
        for i in range(N):
            b = bounds[p][i]
            if b is None:
                continue
            a = ages[p][i]
            limit = fab.S - rho_p - guard
            for (dst, delta, cost, code, delay) in fab.edges[p].get(i, ()):
                if rho_p < guard or delay > limit:
                    continue
                u = ((p + delta) % P) * N + dst
                if bounds[u // N][u % N] is None:
                    return False
                if ages[u // N][u % N] is None:
                    return False
                if bounds[u // N][u % N] > b + cost:
                    return False
                if (bounds[u // N][u % N] == b + cost
                        and ages[u // N][u % N] > a + delta):
                    return False
    return True


def audit(profile, fabric, proposal):
    """Independently verify a plan artifact."""
    try:
        return _audit(profile, fabric, proposal)
    except Exception:
        return {"valid": False}


def _audit(profile, fabric, proposal):
    cal = para.Calibration(profile)
